import axios from 'axios'

const IDENTITER_URL = '/api'

// Configuration d'Axios pour les logs
axios.interceptors.request.use(request => {
  console.log('Request:', {
    method: request.method,
    url: request.url,
    data: request.data,
    headers: request.headers
  })
  return request
})

axios.interceptors.response.use(
  response => {
    console.log('Response:', {
      status: response.status,
      data: response.data,
      headers: response.headers
    })
    return response
  },
  error => {
    console.error('Error:', {
      message: error.message,
      response: error.response?.data,
      status: error.response?.status,
      headers: error.response?.headers
    })
    return Promise.reject(error)
  }
)

export default {
  namespaced: true,

  state: {
    token: localStorage.getItem('token') || null,
    user: JSON.parse(localStorage.getItem('user')) || null,
    isAuthenticated: !!localStorage.getItem('token'),
    pendingVerification: null,
    error: null
  },

  mutations: {
    SET_TOKEN(state, token) {
      state.token = token
      state.isAuthenticated = !!token
      if (token) {
        localStorage.setItem('token', token)
      } else {
        localStorage.removeItem('token')
      }
    },
    SET_USER(state, user) {
      state.user = user
      if (user) {
        localStorage.setItem('user', JSON.stringify(user))
      } else {
        localStorage.removeItem('user')
      }
    },
    SET_PENDING_VERIFICATION(state, data) {
      state.pendingVerification = data
    },
    SET_ERROR(state, error) {
      state.error = error
    }
  },

  actions: {
    async register({ commit }, userData) {
      console.log('Tentative d\'inscription avec les données:', userData)
      try {
        // Formatage des données selon le format attendu par l'API
        const formattedData = {
          nom: userData.nom,
          prenom: userData.prenom,
          username: userData.username,
          email: userData.email,
          password: userData.password,
          date_naissance: userData.dateNaissance,
          ville: userData.ville
        }

        console.log('Données formatées envoyées à l\'API:', formattedData)
        const response = await axios.post(`${IDENTITER_URL}/auth/register`, formattedData)

        console.log('Réponse de l\'API:', response.data)

        if (response.data.success) {
          commit('SET_PENDING_VERIFICATION', {
            email: userData.email,
            message: 'Veuillez vérifier votre email pour le code de vérification'
          })
          commit('SET_ERROR', null)
          return response.data
        } else {
          throw new Error(response.data.message || 'Erreur lors de l\'inscription')
        }
      } catch (error) {
        console.error('Erreur lors de l\'inscription:', error)
        const errorMessage = error.response?.data?.message || error.message || 'Erreur lors de l\'inscription'
        commit('SET_ERROR', errorMessage)
        throw errorMessage
      }
    },

    async verifyEmail({ commit }, { email, verificationCode }) {
      console.log('Tentative de vérification email:', { email, verificationCode })
      try {
        const response = await axios.post(`${IDENTITER_URL}/auth/verify-email`, {
          email,
          verificationCode
        })

        console.log('Réponse de vérification:', response.data)

        if (response.data.success) {
          commit('SET_PENDING_VERIFICATION', null)
          commit('SET_ERROR', null)
          return response.data
        } else {
          throw new Error(response.data.message || 'Erreur lors de la vérification')
        }
      } catch (error) {
        console.error('Erreur lors de la vérification:', error)
        const errorMessage = error.response?.data?.message || error.message || 'Erreur lors de la vérification'
        commit('SET_ERROR', errorMessage)
        throw errorMessage
      }
    },

    async login({ commit }, credentials) {
      console.log('Tentative de connexion:', credentials)
      try {
        const response = await axios.post(`${IDENTITER_URL}/auth/login`, credentials)

        console.log('Réponse de connexion:', response.data)

        // Si 2FA est activé, on attend le code
        if (response.data.requires2FA) {
          commit('SET_PENDING_VERIFICATION', {
            email: credentials.email,
            message: 'Veuillez entrer le code de vérification envoyé par email',
            requires2FA: true
          })
          return response.data
        }

        const { token, user } = response.data
        commit('SET_TOKEN', token)
        commit('SET_USER', user)
        commit('SET_PENDING_VERIFICATION', null)
        commit('SET_ERROR', null)
        return response.data
      } catch (error) {
        console.error('Erreur lors de la connexion:', error)
        const errorMessage = error.response?.data?.message || error.message || 'Erreur lors de la connexion'
        commit('SET_ERROR', errorMessage)
        throw errorMessage
      }
    },

    async verify2FA({ commit }, { email, code }) {
      console.log('Tentative de vérification 2FA:', { email, code })
      try {
        const response = await axios.post(`${IDENTITER_URL}/auth/verify-2fa`, {
          email,
          code
        })
        const { token, user } = response.data
        commit('SET_TOKEN', token)
        commit('SET_USER', user)
        commit('SET_PENDING_VERIFICATION', null)
        commit('SET_ERROR', null)
        return response.data
      } catch (error) {
        console.error('Erreur lors de la vérification 2FA:', error)
        const errorMessage = error.response?.data?.message || error.message || 'Erreur lors de la vérification 2FA'
        commit('SET_ERROR', errorMessage)
        throw errorMessage
      }
    },

    async logout({ commit }) {
      commit('SET_TOKEN', null)
      commit('SET_USER', null)
      commit('SET_PENDING_VERIFICATION', null)
      commit('SET_ERROR', null)
    }
  },

  getters: {
    isAuthenticated: state => state.isAuthenticated,
    user: state => state.user,
    pendingVerification: state => state.pendingVerification,
    error: state => state.error
  }
}
